{
  "technical_and_design_decisions": [
    "Landing page (U1) will be implemented using Spring MVC and Thymeleaf, consistent with existing Spring XD Admin UI technology stack.",
    "RabbitMessageBus retry configuration (U2) will introduce new configuration properties (e.g., `spring.xd.transport.rabbit.retryableExceptions`, `spring.xd.transport.rabbit.nonRetryableExceptions`) at both bus and stream deployment levels, leveraging Spring Retry's `RetryPolicy` and `ExceptionClassifier`.",
    "Kryo deserialization exceptions will be explicitly added to non-retryable list by default, using `org.springframework.amqp.support.converter.MessageConversionException` as the marker.",
    "Dependency upgrades (U3, U4, U5) will be performed by updating version properties in the root Maven POM, followed by a full build and test cycle to resolve any binary incompatibilities.",
    "Module ID and container ID (U6) will be exposed via a new `ModuleContext` bean (request-scoped) and also as environment variables (`MODULE_ID`, `CONTAINER_ID`) in the container process, accessible to user components via `@Autowired` or `System.getenv()`.",
    "Kafka bus configuration overrides (U7) will add new properties under `spring.xd.transport.kafka.consumer.*` and `spring.xd.transport.kafka.producer.*` namespaces, bound to `KafkaMessageBus` consumer/producer factory configuration.",
    "RPM script consolidation (U8) will create a new Git repository `spring-xd-rpm` with a Maven-based build using the `rpm-maven-plugin`, parameterized to produce both base XD and XD+Ambari RPMs from a single source."
  ],
  "assumptions": [
    "The codebase uses Maven as the build tool and has a multi-module structure.",
    "The development team has deep familiarity with Spring XD internals, Spring Integration, Spring AMQP, and Kafka.",
    "Existing unit and integration test suites cover the affected areas (RabbitMessageBus, KafkaMessageBus, module deployment, admin UI).",
    "The landing page is a new endpoint in the existing Spring XD Admin web application (not a separate SPA).",
    "Classloading issues with `MessageConversionException` are due to module classloader isolation; solution involves ensuring the exception class is visible to the module classloader (e.g., by placing `spring-amqp` in the shared classloader domain).",
    "Spring Hadoop 2.2.0 GA is compatible with the current Hadoop distribution versions supported by Spring XD.",
    "Ambari RPM scripts currently exist in a separate internal repository and can be migrated without major changes to the spec file logic.",
    "All estimates assume a single developer working sequentially; no parallelization or ramp-up time included."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "U1: Landing page UI design and implementation",
      "activity_description": "Create Thymeleaf template for landing page with navigation cards/links for Sources, Processors, Sinks, Jobs. Add controller endpoint and integrate with existing admin UI layout and security.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Backend integration for module metadata",
      "activity_description": "Implement REST endpoint or enhance existing module registry service to provide categorized module metadata (source, processor, sink, job) for the landing page links.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "U1: Testing and refinement",
      "activity_description": "Write unit tests for new controller, integration tests for UI navigation, manual verification across browsers, and accessibility checks.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A4",
      "activity_name": "U2: Analyze and design retry configuration",
      "activity_description": "Review current RabbitMessageBus retry logic, Spring Retry integration, and classloading constraints. Design configuration property schema and exception classification strategy.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "U2: Implement retryable exception configuration",
      "activity_description": "Add new configuration properties to RabbitMessageBus, implement `ExceptionClassifier` to distinguish retryable vs non-retryable exceptions, wire into `RetryTemplate` at bus and stream deployment level.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "U2: Handle kryo deserialization and classloading issues",
      "activity_description": "Ensure `org.springframework.amqp.support.converter.MessageConversionException` is on classpath for modules, add default non-retryable rule for kryo deserialization exceptions, test classloader isolation scenarios.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A7",
      "activity_name": "U2: Update documentation and tests",
      "activity_description": "Update reference documentation with new retry configuration options, add unit/integration tests for various exception scenarios, verify backward compatibility.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "U3: Upgrade Spring Integration to 4.1.5",
      "activity_description": "Update SI version in root POM, resolve compile errors due to API changes, update any deprecated usage in codebase, run full test suite.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A9",
      "activity_name": "U3: Test and verify SI upgrade",
      "activity_description": "Execute integration tests focusing on message channels, pollers, and transaction boundaries. Fix any regressions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "U4: Upgrade SI Kafka extension to 1.2.0",
      "activity_description": "Update `spring-integration-kafka` version, resolve dependency conflicts with Kafka client, adapt to any API changes in consumer/producer factories.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A11",
      "activity_name": "U4: Test and verify Kafka extension upgrade",
      "activity_description": "Run Kafka-specific integration tests, verify performance improvements, ensure compatibility with embedded and external Kafka brokers.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A12",
      "activity_name": "U5: Upgrade Spring Hadoop to 2.2.0 GA",
      "activity_description": "Update Spring Hadoop version, resolve breaking changes in HDFS, YARN, MapReduce APIs, update configuration namespaces if needed.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A13",
      "activity_name": "U5: Test and verify Spring Hadoop upgrade",
      "activity_description": "Run Hadoop-related integration tests (batch jobs, HDFS sinks/sources), verify against supported Hadoop distributions.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A14",
      "activity_name": "U6: Design and implement module/container ID exposure",
      "activity_description": "Create `ModuleContext` bean holding moduleId and containerId, populate at module deployment time, expose as environment variables in container process, update module developer guide.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A15",
      "activity_name": "U6: Update documentation and sample modules",
      "activity_description": "Add documentation for accessing module/container IDs, update sample modules to demonstrate logging with IDs.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A16",
      "activity_name": "U7: Implement Kafka bus configuration overrides",
      "activity_description": "Define new configuration properties for consumer (autoCommitEnabled, queueSize, maxWait, fetchSize) and producer (batchSize, batchTimeout), bind to `KafkaMessageBus` factories, allow per-module deployment overrides.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A17",
      "activity_name": "U7: Test and document Kafka overrides",
      "activity_description": "Write integration tests for each override property, verify they affect consumer/producer behavior, update reference documentation.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A18",
      "activity_name": "U8: Consolidate RPM scripts into single repo",
      "activity_description": "Create new Git repository `spring-xd-rpm`, migrate existing RPM spec files and build scripts, parameterize with Maven profiles for base XD and XD+Ambari variants, ensure reproducible builds.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A19",
      "activity_name": "U8: Set up CI/CD and documentation for RPM repo",
      "activity_description": "Configure CI pipeline (e.g., Jenkins/GitHub Actions) to build RPMs on tag push, publish to artifact repository, write README with build instructions and release process.",
      "most_likely_effort": 8
    }
  ],
  "reported_total": {
    "most_likely_effort": 194
  }
}

